mapper.select:
SELECT source_id, target_id, relation_type, weight
FROM memory_links
LIMIT #{limit}

SELECT m.id, m.type, m.scope, m.title, m.content, m.source, m.source_agent, m.status,
       m.importance, m.confidence, m.created_at, m.updated_at
FROM memories m
JOIN memory_links l ON (l.target_id = m.id OR l.source_id = m.id)
WHERE (l.source_id = #{memoryId} OR l.target_id = #{memoryId}) AND m.id != #{memoryId}
LIMIT #{limit}
